import React, { useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import WorkerSplash from "./components/WorkerSplash";
import SignIn from "./components/SignIn";

function App() {
  const [view, setView] = useState("splash");

  // Colors from your specific palette
  const leninBlue = "#A";
  const lemonYellow = "#FFF24D";

  return (
    // The Master Container handles the background color transition
    <motion.div 
      animate={{ backgroundColor: view === "splash" ? "#A1AED1" : lemonYellow }}
      transition={{ duration: 1, ease: [0.16, 1, 0.3, 1] }}
      className="h-screen w-full relative overflow-hidden"
    >
      <AnimatePresence mode="wait">
        {view === "splash" && (
          <motion.div
            key="splash"
            // Slide up and out like a shutter
            exit={{ y: "-100%", opacity: 0 }}
            transition={{ duration: 0.8, ease: [0.76, 0, 0.24, 1] }}
            className="absolute inset-0 z-50"
          >
            <WorkerSplash onComplete={() => setView("signin")} />
          </motion.div>
        )}

        {view === "signin" && (
          <motion.div
            key="signin"
            // Slide up from the bottom into the light
            initial={{ y: "100%", opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
            className="absolute inset-0 z-40 flex items-center justify-center"
          >
            <SignIn onLogin={() => setView("dashboard")} />
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

export default App;
